<?php
require __DIR__.'/app/bootstrap.php';
require __DIR__.'/app/actions.php';
$page=is_string($_GET['page']??null)?$_GET['page']:'home';
if(in_array($page,['checkout','orders'],true))auth();
require __DIR__.'/app/header.php';
if($page==='register'||$page==='login'): ?>
<section class="panel auth-box"><h1><?= $page==='register'?'Tạo tài khoản':'Chào mừng trở lại' ?></h1><form method="post"><?= csrf() ?><input type="hidden" name="action" value="<?= e($page) ?>"><?php if($page==='register')field('name','Họ tên');field('email','Email','','email');field('password','Mật khẩu (8–72 byte)','','password'); ?><button class="btn btn-primary w-100"><?= $page==='register'?'Đăng ký':'Đăng nhập' ?></button></form></section>
<?php elseif($page==='cart'): $rows=cart_rows();$total=0; ?>
<h1>Giỏ hàng của bạn</h1><div class="panel table-responsive"><table class="table"><thead><tr><th>Sản phẩm</th><th>Đơn giá</th><th>Số lượng</th><th>Thành tiền</th></tr></thead><tbody>
<?php foreach($rows as $p): $total+=$p['price']*$p['qty']; ?><tr><td><?= e($p['name']) ?><?= !$p['active']?' (ngừng bán)':'' ?></td><td><?= money($p['price']) ?></td><td><form method="post" class="d-flex gap-2"><?= csrf() ?><input type="hidden" name="action" value="cart_update"><input type="hidden" name="id" value="<?= $p['id'] ?>"><input aria-label="Số lượng" class="form-control qty" type="number" min="0" max="99" name="qty" value="<?= $p['qty'] ?>"><button class="btn btn-outline-primary">Lưu</button><button name="qty" value="0" class="btn btn-outline-danger">Xóa</button></form></td><td><?= money($p['price']*$p['qty']) ?></td></tr><?php endforeach; ?>
</tbody></table><?php if(!$rows): ?><p>Giỏ hàng trống. <a href="index.php">Chọn sản phẩm</a></p><?php else: ?><h3>Tổng: <?= money($total) ?></h3><a class="btn btn-primary" href="index.php?page=checkout">Tiến hành đặt hàng</a><?php endif; ?></div>
<?php elseif($page==='checkout'): ?>
<section class="panel auth-box"><h1>Thông tin nhận hàng</h1><p>Thanh toán COD. Giá và tồn kho được kiểm tra lại khi đặt hàng.</p><form method="post"><?= csrf() ?><input type="hidden" name="action" value="checkout"><?php field('name','Người nhận',user()['name']);field('phone','Số điện thoại','','tel');field('address','Địa chỉ đầy đủ'); ?><p>Tổng tiền hiện tại: <strong><?= money(array_sum(array_map(fn($p)=>$p['price']*$p['qty'],cart_rows()))) ?></strong></p><p>Phí vận chuyển: 0 đ (bản đồ án).</p><button class="btn btn-primary">Xác nhận đặt hàng</button></form></section>
<?php elseif($page==='orders'): ?>
<h1>Đơn hàng của tôi</h1><?php $orders=query('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[user()['id']])->fetchAll();if(!$orders)echo '<p>Bạn chưa có đơn hàng.</p>';foreach($orders as $o): ?>
<section class="panel mb-3"><div class="d-flex justify-content-between flex-wrap"><h3>Đơn #<?= $o['id'] ?></h3><span class="badge text-bg-primary align-self-start"><?= e(STATUSES[$o['status']]) ?></span></div><p><?= e($o['created_at']) ?> · <?= e($o['receiver']) ?> · <?= e($o['phone']) ?><br><?= e($o['address']) ?></p><ul><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $i): ?><li><?= e($i['product_name']) ?> × <?= $i['quantity'] ?> — <?= money($i['price']*$i['quantity']) ?></li><?php endforeach; ?></ul><strong>Tổng: <?= money($o['total']) ?></strong></section><?php endforeach; ?>
<?php elseif($page==='product'): $id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT)?:0;$p=query('SELECT * FROM products WHERE id=? AND active=1',[$id])->fetch();if(!$p): http_response_code(404); ?><h1>Không tìm thấy sản phẩm</h1><?php else: ?>
<div class="row g-4"><div class="col-md-6"><img class="detail-img" src="assets/<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"></div><div class="col-md-6 panel"><p class="eyebrow">PHỤ KIỆN ĐIỆN THOẠI</p><h1><?= e($p['name']) ?></h1><h2 class="text-primary"><?= money($p['price']) ?></h2><p>Tương thích: <?= e($p['compatible']) ?></p><p><?= nl2br(e($p['description'])) ?></p><p>Còn <?= $p['stock'] ?> sản phẩm</p><form method="post"><?= csrf() ?><input type="hidden" name="action" value="cart_add"><input type="hidden" name="id" value="<?= $p['id'] ?>"><?php field('qty','Số lượng',1,'number'); ?><button class="btn btn-primary" <?= !$p['stock']?'disabled':'' ?>>Thêm vào giỏ</button></form></div></div>
<?php endif; elseif($page==='home'):
$q=is_string($_GET['q']??null)?trim($_GET['q']):'';$cat=filter_var($_GET['category']??0,FILTER_VALIDATE_INT)?:0;$sort=is_string($_GET['sort']??null)?$_GET['sort']:'';
$sortSql=['low'=>'price ASC','high'=>'price DESC'][$sort]??'id DESC';
$sql='SELECT * FROM products WHERE active=1';$args=[];
if($q!==''){$sql.=' AND (name LIKE ? OR compatible LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($cat){$sql.=' AND category_id=?';$args[]=$cat;}
$min=filter_var($_GET['min']??'',FILTER_VALIDATE_INT);$max=filter_var($_GET['max']??'',FILTER_VALIDATE_INT);
if($min!==false&&$min>=0){$sql.=' AND price>=?';$args[]=$min;}if($max!==false&&$max>=0){$sql.=' AND price<=?';$args[]=$max;}
$products=query($sql.' ORDER BY '.$sortSql,$args)->fetchAll(); ?>
<section class="hero mb-4"><div><p class="eyebrow">NHỎ GỌN · TIỆN ÍCH · ĐÚNG GU</p><h1>Phụ kiện xinh.<br>Trải nghiệm chất.</h1><p>Chọn phụ kiện phù hợp cho chiếc điện thoại của bạn.</p><a href="#products" class="btn btn-light">Khám phá sản phẩm →</a></div><img src="assets/case.svg" alt="Minh họa ốp điện thoại"></section>
<section id="products"><h2>Sản phẩm của cửa hàng</h2><form method="get" class="panel filters mb-4"><input class="form-control" name="q" placeholder="Tìm sản phẩm / dòng máy" aria-label="Tìm kiếm" value="<?= e($q) ?>"><select class="form-select" name="category" aria-label="Danh mục"><option value="0">Tất cả danh mục</option><?php foreach(query('SELECT * FROM categories ORDER BY name')->fetchAll() as $c): ?><option value="<?= $c['id'] ?>" <?= $cat==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><input class="form-control" name="min" type="number" min="0" placeholder="Giá từ" aria-label="Giá từ" value="<?= $min===false?'':e($min) ?>"><input class="form-control" name="max" type="number" min="0" placeholder="Giá đến" aria-label="Giá đến" value="<?= $max===false?'':e($max) ?>"><select class="form-select" name="sort" aria-label="Sắp xếp"><option value="">Mới nhất</option><option value="low" <?= $sort==='low'?'selected':'' ?>>Giá tăng dần</option><option value="high" <?= $sort==='high'?'selected':'' ?>>Giá giảm dần</option></select><button class="btn btn-primary">Lọc</button></form><div class="row g-4">
<?php if(!$products)echo '<p>Không có sản phẩm phù hợp.</p>';foreach($products as $p): ?><div class="col-6 col-lg-3"><article class="card h-100"><a href="index.php?page=product&id=<?= $p['id'] ?>"><img class="card-img-top" src="assets/<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"></a><div class="card-body"><small class="text-secondary"><?= e($p['compatible']) ?></small><h3 class="h6 mt-2"><a class="product-link" href="index.php?page=product&id=<?= $p['id'] ?>"><?= e($p['name']) ?></a></h3><strong class="text-primary"><?= money($p['price']) ?></strong><p class="small mt-2"><?= $p['stock']?'Còn hàng':'Hết hàng' ?></p></div></article></div><?php endforeach; ?></div></section>
<?php else: http_response_code(404); ?><h1>Trang không tồn tại</h1><?php endif; require __DIR__.'/app/footer.php'; ?>
